package macro;
import star.common.*;import star.base.neo.*;import star.base.report.*;import star.vis.*;import java.nio.file.*;import java.util.*;
public class InspectMeshFailure extends StarMacro{
public void execute(){Simulation s=getActiveSimulation();Path root=Paths.get("F:/ntnu/flap_control/hydro_validation_2606_20261102");try{
Path input=Paths.get(s.getSessionPath()).toAbsolutePath().normalize();if(!input.startsWith(root.resolve("cases")))throw new IllegalStateException("Own working case only");Path out=input.getParent().resolve("mesh_diagnostic_"+System.getenv("NTNU_HYDRO_RUN_ID"));Files.createDirectories(out);
s.getSimulationIterator().getAutoSave().setEnabled(false);s.getSimulationIterator().getAutoSave().setAutoSaveBatch(false);List<Region> rs=new ArrayList<>(s.getRegionManager().getRegions());FvRepresentation rep=(FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh");
StringBuilder b=new StringBuilder("input="+input+"\ntime="+s.getSolution().getPhysicalTime()+"\ncells="+rep.getCellCount()+"\n");
for(String n:List.of("Volume","CellQuality","FaceValidity")){MinReport mi=s.getReportManager().createReport(MinReport.class);mi.getParts().setObjects(rs);mi.setSmooth(false);List<FieldFunction> xyz=List.of(s.getFieldFunctionManager().getFunction("Position").getComponentFunction(0),s.getFieldFunctionManager().getFunction("Position").getComponentFunction(1),s.getFieldFunctionManager().getFunction("Position").getComponentFunction(2));mi.setCollocatedFieldFunctions(xyz);mi.setFieldFunction(s.getFieldFunctionManager().getFunction(n));mi.setRepresentation(rep);b.append(n+" min="+mi.getReportMonitorValue());for(FieldFunction f:xyz)b.append(" "+mi.getCollocatedValue(f));b.append("\n");}
XyzInternalTable tab=s.getTableManager().createTable(XyzInternalTable.class);tab.getParts().setObjects(rs);tab.setRepresentation(rep);tab.setExtractVertexData(false);List<FieldFunction> ff=new ArrayList<>();for(String n:List.of("Volume","CellQuality","FaceValidity","PrismLayerNumber","PrismCellThickness"))if(s.getFieldFunctionManager().hasFunction(n))ff.add(s.getFieldFunctionManager().getFunction(n));tab.setFieldFunctions(ff);tab.extract();tab.export(out.resolve("all_mesh_cells.csv").toString());
UserFieldFunction mask=s.getFieldFunctionManager().createFieldFunction();mask.setFunctionName("InspectionBadCells");mask.setPresentationName("Inspection bad cells");mask.getTypeOption().setSelected(FieldFunctionTypeOption.Type.SCALAR);mask.setDefinition("($Volume <= <0 m^3> || $CellQuality <= 0 || $FaceValidity < 0.5) ? 1 : 0");ThresholdPart bad=s.getPartManager().createThresholdPart();bad.getInputParts().setObjects(rs);bad.setFieldFunction(mask);bad.setMode(ThresholdMode.BETWEEN_TAG);bad.setRange(new DoubleVector(new double[]{.5,1.5}));
Scene sc=s.getSceneManager().createScene("Mesh failure diagnosis");sc.initializeAndWait();PlaneSection plane=s.getPartManager().createImplicitPart(rs,List.of(0.,1.,0.),List.of(0.,.02,0.),0,1,new DoubleVector(new double[]{0}));PartDisplayer m=sc.getDisplayerManager().createPartDisplayer("midspan mesh",-1,1);m.getInputParts().setObjects(plane);m.setRepresentation(rep);m.setMesh(true);m.setSurface(false);m.setOutline(false);m.setDisplayerColor(new DoubleVector(new double[]{.35,.4,.45}));PartDisplayer d=sc.getDisplayerManager().createPartDisplayer("invalid cells",-1,1);d.getInputParts().setObjects(bad);d.setRepresentation(rep);d.setSurface(true);d.setOutline(true);d.setDisplayerColor(new DoubleVector(new double[]{1,.05,.05}));
List<Boundary> walls=new ArrayList<>();for(Region r:rs)for(Boundary w:r.getBoundaryManager().getBoundaries())if(w.getPresentationName().contains("Hydro_Main")||w.getPresentationName().contains("Hydro_Flap"))walls.add(w);PartDisplayer w=sc.getDisplayerManager().createPartDisplayer("foil",-1,1);w.getInputParts().setObjects(walls);w.setSurface(true);w.setDisplayerColor(new DoubleVector(new double[]{.05,.3,.65}));
double[][] views={{.60,.025,.68},{.952,.02128173276776986,.065},{1.18,0,.045}};String[] names={"foil","hinge","trailing_edge"};for(int i=0;i<views.length;i++){double[] v=views[i];sc.getCurrentView().setInput(new DoubleVector(new double[]{v[0],.02,v[1]}),new DoubleVector(new double[]{v[0],-3,v[1]}),new DoubleVector(new double[]{0,0,1}),v[2],1,s.getCoordinateSystemManager().getLabCoordinateSystem(),false);sc.printAndWait(out.resolve(names[i]+".png").toString(),1,1200,800);}
Files.writeString(out.resolve("diagnostic.txt"),b.toString());s.println("MESH_DIAGNOSTIC_EXPORTED_NO_SOLVER_STEPS_NO_SIM_SAVE "+out);
}catch(Exception e){throw new RuntimeException(e);}}
}
